"""Approved V3 board frame. The dated image is still generated by the career UI."""
from pathlib import Path
import hashlib,json
import numpy as np
from room_prop_conversion import Palette,merged_parts
from room_visual_r68 import VERT,packed
from room_interior_r72 import write_groups
from room_native_hanging_20261022 import texture_package

SOURCE='ModCarrerMode/data/club_environment/room/next_match_board'
LEGACY_KEYS=frozenset(('role_neutral_19','role_neutral_20','role_neutral_21'))
DISPLAY_LO=np.array([-117.5,1094,-512.55])
DISPLAY_HI=np.array([117.5,1242,-512.55])


def geometry(game):
    folder=Path(game)/SOURCE
    spec=json.loads((folder/'board-frame.json').read_text(encoding='utf8'))
    if spec.get('schema')!=1 or spec.get('units')!='cm':raise ValueError('Unsupported next-match board geometry')
    palette=Palette();parts={key:[] for key in ('metal','dark','white','rubber','markers')}
    with np.load(folder/'board-frame.npz',allow_pickle=False) as cache:
        for row in spec['parts']:
            p=cache[row['prefix']+'_p'];n=cache[row['prefix']+'_n'];key=row['group']
            if p.shape!=n.shape or p.ndim!=2 or p.shape[1]!=3 or len(p)%3 or len(p)>60000:
                raise ValueError('Invalid next-match board mesh')
            if not np.isfinite(p).all() or not np.isfinite(n).all():raise ValueError('Invalid board vertex')
            if not ((p>=[-125,1000,-560])&(p<=[125,1250,-475])).all():raise ValueError('Board exceeds its existing scene envelope')
            uv=np.tile(palette.uv(row['color_linear'],linear=True),(len(p),1))
            parts[key].append(dict(p=p,n=n,uv=uv,idx=np.arange(len(p),dtype=np.uint32)))
    groups={}
    for key,batches in parts.items():
        if not batches:raise ValueError('Missing board material: '+key)
        groups[key]=[]
        for mesh in merged_parts(batches):
            v=np.zeros(len(mesh['positions']),dtype=VERT)
            v['p']=mesh['positions'];v['uv']=mesh['uvs']
            for i,normal in enumerate(mesh['normals']):
                v['n'][i]=packed(normal)
                ref=np.array([0.,1.,0.]) if abs(normal[0])>.9 else np.array([1.,0.,0.])
                tangent=ref-normal*np.dot(ref,normal);tangent/=max(1e-9,np.linalg.norm(tangent))
                v['g'][i]=packed(tangent)
            groups[key].append((v,mesh['indices'].astype('<u2')))
    return groups,palette.image(),spec


def stage(game,output):
    import room_v3
    game,output=Path(game),Path(output);output.mkdir(parents=True,exist_ok=True)
    groups,image,spec=geometry(game)
    target=output/'next_match_board.rx3'
    bindings=write_groups(game/room_v3.OLD/'locker_support_r68.rx3',groups,target)
    model='next_match_board_'+hashlib.sha256(target.read_bytes()).hexdigest()[:14]+'.rx3'
    (output/model).write_bytes(target.read_bytes())
    texture='next_match_board_palette_'+hashlib.sha256(image.tobytes()).hexdigest()[:14]+'.rx3'
    texture_package(image,output/texture,'v3_cm')
    return dict(model=model,texture=texture,bindings=bindings,dynamic_image=spec['dynamic_image'],
                replaces=sorted(LEGACY_KEYS),source_meshes=len(spec['parts']))


def replaces(key,manifest):
    # Compatibility: a V3 installation without the new model keeps its frame.
    return bool(manifest.get('next_match_board')) and key in LEGACY_KEYS


def prepare(manifest,add,identity):
    import room_v3
    board=manifest.get('next_match_board')
    if not board:return
    for binding in board['bindings']:
        add('v3_next_match_board_'+binding['material'],room_v3.PREFIX+board['model'],
            room_v3.PREFIX+board['texture'],'v3_cm',identity,submesh=binding['submesh'])
